package org.hkvc.donate;

import java.util.*;

final class Validation {
    static void require(boolean test,String message){if(!test)throw new Application.Failure(400,message);}
    static boolean integer(Object value){return value instanceof Number n&&Double.isFinite(n.doubleValue())&&n.doubleValue()==Math.rint(n.doubleValue());}
    static int integer(Object value,int min,int max,String message){require(integer(value),message);double n=((Number)value).doubleValue();require(n>=min&&n<=max,message);return (int)n;}
    static String id(Object value){require(value instanceof String&&((String)value).matches("[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"),"Invalid identifier");return (String)value;}
    static Map<String,Object> donor(Map<String,Object> b){var out=new LinkedHashMap<String,Object>();var limits=Application.map("prefix",40,"englishName",150,"chineseName",100,"phone",50,"email",180);
        for(var entry:limits.entrySet()){Object value=b.getOrDefault(entry.getKey(),"");require(value instanceof String&&((String)value).length()<=(int)entry.getValue()&&!((String)value).matches("(?s).*[\\x00-\\x1f].*"),"Invalid "+entry.getKey());out.put(entry.getKey(),((String)value).trim());}
        out.put("email",((String)out.get("email")).toLowerCase(Locale.ROOT));require(!out.get("englishName").equals(""),"English full name is required");require(((String)out.get("email")).matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"),"Valid email is required");return out;
    }
    static final List<String> CATEGORIES=List.of("tree","airport","card","ticket");
    static boolean image(Object o){return o instanceof String s&&s.length()<=2000&&((s.startsWith("/")&&!s.startsWith("//"))||s.startsWith("https://"));}
    static void bilingual(Object value,int max,String error){var m=Application.object(value);for(String lang:List.of("zh","en"))require(m.get(lang) instanceof String&&((String)m.get(lang)).length()<=max,error);}
    static Map<String,Object> config(Object value){var c=Application.object(value);require(Application.JSON.valueToTree(c).toString().length()<=200000,"Content too large");
        var copy=Application.object(c.get("copy"));for(String lang:List.of("zh","en")){var text=Application.object(copy.get(lang));for(var e:text.entrySet())require(e.getKey().matches("[a-zA-Z]\\w*")&&e.getValue() instanceof String&&((String)e.getValue()).length()<=4000,"Invalid text");}
        var t=Application.object(c.get("theme"));for(String key:List.of("primary","background","surface","accent"))require(Application.string(t,key).matches("#[0-9a-fA-F]{6}"),"Invalid colour");
        for(String key:List.of("logo","logoSecondary","art"))require(key.equals("logoSecondary")&&t.get(key)==null||image(t.get(key)),"Invalid image URL");
        require(List.of("sans","serif").contains(t.get("font"))&&List.of("sidebar","top").contains(t.get("navigation")),"Invalid layout");integer(t.get("width"),900,1800,"Invalid layout");
        require(t.get("brand") instanceof String&&((String)t.get("brand")).length()<=100&&t.get("radius") instanceof Number&&((Number)t.get("radius")).doubleValue()>=0&&((Number)t.get("radius")).doubleValue()<=40,"Invalid appearance");integer(c.get("demoPoints"),0,10000000,"Invalid demo points");
        var cats=Application.list(c.get("categories"));require(cats.size()==4,"Invalid categories");var ids=new HashSet<>();for(var raw:cats){var cat=Application.object(raw);require(CATEGORIES.contains(cat.get("id"))&&ids.add(cat.get("id"))&&cat.get("enabled") instanceof Boolean&&cat.get("icon") instanceof String&&((String)cat.get("icon")).length()<=8,"Invalid categories");Object cover=cat.get("cover");require(cover==null||cover.equals("")||image(cover),"Invalid cover image URL");}
        var items=Application.list(c.get("items"));require(items.size()<=80,"Too many items");ids.clear();for(Object raw:items){var i=Application.object(raw);require(List.of("airport","ticket").contains(i.get("category"))&&i.get("id") instanceof String&&ids.add(i.get("id"))&&i.get("enabled") instanceof Boolean,"Invalid reward");integer(i.get("points"),i.get("category").equals("airport")?1000:0,10000000,"Invalid reward");if(i.get("category").equals("ticket"))require(List.of("tickets","discount").contains(i.get("mode")),"Invalid reward");bilingual(i.get("title"),120,"Invalid reward text");bilingual(i.get("description"),2000,"Invalid reward text");}
        var fields=Application.object(c.get("fields"));for(String cat:CATEGORIES){var array=Application.list(fields.get(cat));require(array.size()<=25,"Invalid fields");ids.clear();for(Object raw:array){var f=Application.object(raw);String key=Application.string(f,"key");require(key.matches("[a-zA-Z]\\w{0,39}")&&ids.add(key)&&!List.of("customerName","customerEmail","rewardId","constructor","prototype","submit").contains(key)&&List.of("text","textarea","select","number","date","email").contains(f.get("type"))&&f.get("required") instanceof Boolean,"Invalid field");bilingual(f.get("label"),120,"Invalid field label");if("select".equals(f.get("type"))){var options=Application.list(f.get("options"));require(!options.isEmpty()&&options.size()<=30,"Invalid choices");for(Object o:options)bilingual(o,100,"Invalid choices");}for(String k:List.of("min","max","maxLength"))if(f.get(k)!=null)require(f.get(k) instanceof Number n&&Double.isFinite(n.doubleValue())&&Math.abs(n.doubleValue())<=10000,"Invalid field limits");}}
        return c;
    }
    static List<List<String>> csv(String input){require(input.length()<=2*1024*1024,"CSV exceeds 2 MB");String text=input.replaceFirst("^\\uFEFF","");var rows=new ArrayList<List<String>>();var row=new ArrayList<String>();var value=new StringBuilder();boolean quoted=false,closed=false;
        for(int i=0;i<text.length();i++){char ch=text.charAt(i);if(quoted){if(ch=='"'){if(i+1<text.length()&&text.charAt(i+1)=='"'){value.append('"');i++;}else{quoted=false;closed=true;}}else value.append(ch);continue;}
            if(ch=='"'){require(value.length()==0&&!closed,"Invalid CSV quoting");quoted=true;}else if(ch==','){row.add(value.toString());value.setLength(0);closed=false;}else if(ch=='\r'||ch=='\n'){if(ch=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;row.add(value.toString());if(row.stream().anyMatch(s->!s.isBlank()))rows.add(row);row=new ArrayList<>();value.setLength(0);closed=false;}else{require(!closed||Character.isWhitespace(ch),"Invalid CSV quoting");if(!closed)value.append(ch);}}
        require(!quoted,"Unclosed CSV quote");row.add(value.toString());if(row.stream().anyMatch(s->!s.isBlank()))rows.add(row);require(rows.size()>=2&&rows.size()<=501,"CSV needs a header and 1–500 donors");return rows;
    }
    static List<Map<String,Object>> donorCsv(String text){var rows=csv(text);var headers=rows.get(0);Map<String,List<String>> aliases=Map.of(
        "prefix",List.of("prefix","title","sal","salutation","稱謂","称谓"),"englishName",List.of("englishfullname","englishname","fullname","name","英文姓名","英文全名"),"chineseName",List.of("chinesefullname","chinesename","中文姓名","中文全名"),"phone",List.of("phone","telephone","tel","mobile","contactno","contactnumber","電話","电话","聯絡電話"),"email",List.of("email","emailaddress","電郵","邮箱","郵箱","電子郵件"));
        var indices=new HashMap<String,Integer>();for(var entry:aliases.entrySet()){int index=-1;for(int i=0;i<headers.size();i++)if(entry.getValue().contains(headers.get(i).trim().toLowerCase(Locale.ROOT).replaceAll("[\\s_\\-().]",""))){require(index==-1,"Duplicate header for "+entry.getKey());index=i;}indices.put(entry.getKey(),index);}
        require(indices.get("englishName")>=0&&indices.get("email")>=0,"Missing English full name or email column");var result=new ArrayList<Map<String,Object>>();var seen=new HashSet<>();for(int i=1;i<rows.size();i++){var row=rows.get(i);require(row.size()==headers.size(),"CSV row "+(i+1)+": column count differs from header");var b=new HashMap<String,Object>();indices.forEach((k,v)->b.put(k,v<0?"":row.get(v)));var d=donor(b);require(seen.add(d.get("email")),"Duplicate email in CSV");result.add(d);}return result;
    }
}
